/** Hand-drawn anatomical muscle map (original artwork for MusclePro).
 *
 *  Each view is authored as the LEFT half of a 400×880 figure (x < 200) in
 *  absolute M/L/C/Z path commands. The right half is generated by mirroring,
 *  and the female figure is produced by a smooth width warp of every
 *  coordinate (narrower shoulders and waist, wider hips) plus a few
 *  replacement shapes — one source of truth for four figures.
 */
import type { BodyType, Muscle } from '../types';

export type View = 'front' | 'back';
type Kind = 'muscle' | 'minor' | 'skin' | 'line';

interface Part {
  d: string;
  m?: Muscle; // clickable muscle group
  kind?: Kind; // default 'muscle' when m is set, else 'skin'
  center?: boolean; // spans the midline: drawn once, not mirrored
  only?: BodyType; // shape used for one body type only
}

