// ------------------------------------------------------------ geometry
type Fn = (x: number, y: number) => [number, number];

function mapPath(d: string, fn: Fn): string {
  const tokens = d.match(/[MLCZ]|-?\d*\.?\d+/g) ?? [];
  const out: string[] = [];
  let i = 0;
  while (i < tokens.length) {
    const tok = tokens[i];
    if (/[MLCZ]/.test(tok)) {
      out.push(tok);
      i++;
      continue;
    }
    const [x, y] = fn(parseFloat(tok), parseFloat(tokens[i + 1]));
    out.push(`${x.toFixed(1)} ${y.toFixed(1)}`);
    i += 2;
  }
  return out.join(' ');
}

const mirror: Fn = (x, y) => [400 - x, y];

/** Piecewise-linear remap through (input, output) keyframes. */
function remap(v: number, keys: [number, number][]): number {
  for (let i = 1; i < keys.length; i++) {
    const [a1, b1] = keys[i];
    const [a0, b0] = keys[i - 1];
    if (v <= a1) return b0 + ((v - a0) / (a1 - a0)) * (b1 - b0);
  }
  return keys[keys.length - 1][1];
}

// Proportions: the art is authored with a long torso; this sets classic
// 8-head proportions (shorter trunk, longer legs) without redrawing.
const HEIGHT_KEYS: [number, number][] = [[0, 0], [280, 280], [504, 466], [650, 646], [880, 880]];
const proportion: Fn = (x, y) => [x, remap(y, HEIGHT_KEYS)];

// Female silhouette: width multiplier by height (piecewise, smoothed).
const FEMALE_K: [number, number][] = [
  [0, 0.93], [125, 0.93], [160, 0.87], [280, 0.89], [390, 0.86], [450, 1.0], [520, 1.06], [640, 1.01], [880, 0.97],
];
function femaleK(y: number): number {
  for (let i = 1; i < FEMALE_K.length; i++) {
    const [y1, k1] = FEMALE_K[i];
    const [y0, k0] = FEMALE_K[i - 1];
    if (y <= y1) {
      const t = (y - y0) / (y1 - y0);
      const s = t * t * (3 - 2 * t); // smoothstep
      return k0 + (k1 - k0) * s;
    }
  }
  return FEMALE_K[FEMALE_K.length - 1][1];
}
const femaleWarp: Fn = (x, y) => [200 + (x - 200) * femaleK(y), y];

// ------------------------------------------------------------- render
export interface AnatomyOptions {
  label?: (m: Muscle) => string;
  interactive?: boolean;
}

/** Render one view as an <svg> string. Muscle groups are <g data-muscle>. */
export function renderAnatomy(view: View, body: BodyType, opts: AnatomyOptions = {}): string {
  const parts = (view === 'front' ? FRONT : BACK).filter((p) => !p.only || p.only === body);
  const warp: Fn = body === 'female' ? (x, y) => proportion(...femaleWarp(x, y)) : proportion;
  const groups = new Map<Muscle, string[]>();
  const layers: Record<Exclude<Kind, 'muscle'>, string[]> = { skin: [], minor: [], line: [] };

  for (const p of parts) {
    const ds = [mapPath(p.d, warp)];
    if (!p.center) ds.push(mapPath(p.d, (x, y) => warp(...mirror(x, y))));
    if (p.m) {
      const list = groups.get(p.m) ?? [];
      list.push(...ds);
      groups.set(p.m, list);
    } else {
      layers[p.kind === 'line' || p.kind === 'minor' ? p.kind : 'skin'].push(...ds);
    }
  }

  const path = (cls: string) => (d: string) => `<path class="${cls}" d="${d}"/>`;
  const muscles = [...groups.entries()]
    .map(([m, ds]) => {
      const label = opts.label ? opts.label(m) : m;
      const a11y = opts.interactive
        ? ` role="button" tabindex="0" aria-label="${label.replace(/"/g, '&quot;')}" aria-pressed="false"`
        : '';
      return `<g class="mg" data-muscle="${m}"${a11y}>${ds.map(path('mp-m')).join('')}</g>`;
    })
    .join('');

  return `<svg class="anatomy" viewBox="0 0 400 880" xmlns="http://www.w3.org/2000/svg" data-view="${view}" role="group">
    <g class="mp-skin-layer">${layers.skin.map(path('mp-skin')).join('')}</g>
    <g class="mp-minor-layer">${layers.minor.map(path('mp-minor')).join('')}</g>
    <g class="mp-muscles">${muscles}</g>
    <g class="mp-line-layer" aria-hidden="true">${layers.line.map(path('mp-line')).join('')}</g>
  </svg>`;
}
